def _kernel(texture_type: int):
    if texture_type <= 50:
        from ._procedural_basic import render_basic as k
    elif texture_type <= 70:
        from ._procedural_showcase import render_showcase as k
    else:
        from ._procedural_sim import render_simulation as k
    return k


def _wrap_i32(v: int) -> int:
    v &= 0xFFFFFFFF
    return v - (1 << 32) if v >= (1 << 31) else v


def render_fast_noise(texture_type: int, width: int, height: int, seed: int, params, colors) -> np.ndarray:
    """Render native texture ``texture_type`` -> float32 (H, W, 4).

    ``params`` = [scale, value1..value5] (rounded to float32 like the JNI float[]),
    ``colors`` = ARGB ints in native order.
    """
    p = np.asarray(params, np.float32).astype(np.float64)
    c = np.asarray(colors, np.uint32)
    packed = _kernel(texture_type)(int(texture_type), int(width), int(height), _wrap_i32(BASE_SEED + int(seed)), p, c)
    return argb_to_rgba(packed)


def _make_render(texture_type, show_scale, scale_default, value_names, color_names):
    def render(width, height, seed, v):
        scale = v["scale"] if show_scale else scale_default
        params = [scale] + [v[n] for n in value_names]
        colors = colors_argb([v[n] for n in color_names])
        return render_fast_noise(texture_type, width, height, seed, params, colors)

    return render


def _register_all() -> None:
    for ttype, upstream, pid, title, category, show_scale, scale, values, colors in _TABLE:
        params = []
        if show_scale:
            params.append(Float("scale", scale, title="Scale", min=0.001, max=0.05, step=0.0001,
                                description="Noise frequency (feature size ~ 1/scale pixels)"))
        for name, ptitle, lo, hi, default, decimals in values:
            params.append(Float(name, default, title=ptitle, min=lo, max=hi, step=10.0 ** -decimals))
        for name, ctitle, argb in colors:
            params.append(Color(name, argb_hex(argb), title=ctitle))
        register(TexturePreset(
            id=pid, title=title, category=category, backend="fast-noise", upstream=upstream, params=params,
            render_fn=_make_render(ttype, show_scale, scale, [v[0] for v in values], [c[0] for c in colors]),
            notes=("" if show_scale else "Scale is fixed at the ImageToolbox default (not exposed in its UI). ")
            + "Native texture #%d; float64 port of the float32 C++ (see port report)." % ttype,
        ))


_register_all()
